def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    strong_pressure = 0
    weak_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if bid >= 140:
                    strong_pressure += 1
                if bid <= 60:
                    weak_count += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    # Scarcity estimate: with supply 15-25 and req 13, low supply is much tighter.
    if supply <= 16:
        scarcity = 'high'
    elif supply <= 20:
        scarcity = 'medium'
    else:
        scarcity = 'low'

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    emergency = hp <= 3 or no_water_days >= 2
    caution = hp <= 5 or no_water_days >= 1

    if emergency:
        if scarcity == 'high':
            bid = max(150.0, max_prev + 3.0)
        elif scarcity == 'medium':
            bid = max(120.0, avg_prev + 2.0)
        else:
            bid = max(95.0, avg_prev)
    elif caution:
        if scarcity == 'high':
            bid = max(110.0, avg_prev + 1.5)
        elif scarcity == 'medium':
            bid = 72.0 if max_prev < 100 else max(82.0, avg_prev - 8.0)
        else:
            bid = 38.0 if strong_pressure >= 2 else 52.0
    else:
        if scarcity == 'high':
            bid = 88.0 if strong_pressure >= 2 else max(76.0, avg_prev - 18.0)
        elif scarcity == 'medium':
            bid = 34.0 if strong_pressure >= 2 else 48.0
        else:
            bid = 12.0 if day < 8 else 22.0

    # Late-game survival adjustment.
    if day >= 8 and hp <= 5:
        bid = max(bid, 90.0 if scarcity != 'low' else 60.0)

    # Avoid burning out too early.
    reserve_floor = 0.0
    if day <= 6:
        reserve_floor = 140.0
    elif day <= 8:
        reserve_floor = 70.0

    affordable = budget
    if budget > reserve_floor:
        affordable = budget - reserve_floor + min(reserve_floor * 0.25, 25.0)

    bid = min(bid, affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 4:
                return min(my_status['budget'], DAILY_SALARY * 0.5)
            else:
                return min(my_status['budget'], DAILY_SALARY * 0.9)

        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid + 2.0))

        else:
            if my_status['hp'] > 6:
                return min(my_status['budget'], DAILY_SALARY * 0.4)
            else:
                return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 1.0))

    current_day = day_context['day']
    if current_day <= EPISODE_DAYS / 3:
        return min(my_status['budget'], DAILY_SALARY * 0.6)
    elif current_day <= EPISODE_DAYS * 2 / 3:
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 100

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.5)

    if day_context['day'] > 7:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    target_bid = min(avg_opp_bid * 0.95, DAILY_SALARY * 1.1)
    return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.6))
